-- ============================================================
-- 政策雷达 · 初始数据：启用的数据源 + 关键词
-- 执行方式: psql -d <database> -f policy-seed.sql
-- 在 schema.sql 之后执行，代替早期的 init-data.sql。可重复执行：已存在的行不会被覆盖。
-- 内容导出自线上实际使用的配置（只含启用的数据源），全部是公开网址与关键词。
-- ============================================================

-- 这几列平时由应用首次运行时自动补上；这里先补，保证本文件能单独执行
alter table monitor_sources add column if not exists language text not null default 'zh';
alter table monitor_sources add column if not exists region text not null default 'domestic';
alter table monitor_sources add column if not exists content_category text not null default 'general';

-- 数据源
on conflict (id) do nothing;

-- 关键词（用于相关度打分与分类）
on conflict (id) do nothing;
